catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   //Type appropriate comment here, and begin script below  
		var selected_room= g_form.getValue('room_location');
		if (selected_room =='Conference Center'){
			g_form.setReadOnly('requested_room',false);
			g_form.clearValue('requested_room',true);
			g_form.clearValue('event_end_date',true);
			g_form.setReadOnly('requested_room',true);	
			//g_form.addInfoMessage("Cleared End Date");
			if (g_form.getValue('event_end_date')== ''){
				//g_form.addInfoMessage(g_form.getValue('event_end_date'));
			g_form.setReadOnly('requested_room',true);			
			}
		}
}
